  isTabby
  __typename
}

fragment DogInfo on Dog {
  hasBrindleCoat
  __typename
}

fragment PetInfo on Pet {
  id
  name
  age
  ... on Cat {
    ...CatInfo
    __typename
  }
  ... on Dog {
    ...DogInfo
    __typename
  }
  __typename
}

{
  pets {
    ...PetInfo
    __typename
  }
}

